mapper.select:
select s.PA,s.PB,s.id,u.user_name userName, s.user_id, s.top_name, s.top_type,  s.signing_data, s.validity_Date,o.createtime, o.agreeurl,o.filingurl,s.first_person_id,  s.second_person_id, s.third_person_id, fourth_person_id,  s.amount, amount, s.contract, s.filing, s.state
from sci_IntraSchPro_apply s left join sci_IntraSchPro_over o on s.id=o.appid left join sys_user u on  s.user_id=u.user_id

where s.id = #{id}
